import {p,code,table,req,diagram,qa,refs,warn,section} from './lesson-helpers.mjs';
import {additionalLessons} from './lesson-expansion.mjs';
import {deepenLessons} from './learning-bridges.mjs';
export const lessons=[
{
slug:'scalability',title:'Scalability',heading:'Grow an application without moving the bottleneck blindly',
intro:'Follow an order service from one instance to a load-balanced system. Learn to measure demand, find the constraint, and preserve correctness while adding capacity.',
definition:'Scalability is a system’s ability to handle increasing workload by adding resources while maintaining acceptable performance, cost, and correctness. Capacity is how much it can currently sustain; elasticity is how quickly resources adapt to changing demand.',
prerequisites:'Know what an HTTP request and database query are. The <a href="index.html#requirements">API requirements section</a> explains latency, throughput, and invariants. No Kubernetes knowledge is required.',
outcome:'Explain why adding application replicas helps some workloads and hurts others, then propose a measured scaling plan.',
sections:[
section('problem','One service meets a sale-day spike',p('Our shop begins with one Java process and one SQL database. At 50 requests per second, orders respond quickly. During a sale, traffic reaches 1,000 requests per second. Requests wait; customers retry; more work arrives. A larger queue does not create processing capacity—it mostly delays the moment callers discover overload.')+p('Before adding replicas, ask where time is spent. If CPU is saturated, more application compute may help. If every request waits for a slow query, more replicas can send even more competing queries to the same database. The visible symptom is slow HTTP; the limiting resource may be somewhere else.')+p('A bottleneck is the resource that limits useful throughput for the current workload. It can shift after every improvement. Treat scaling as a sequence of measured changes rather than one architecture diagram.')),
section('requirements','State demand and success first',req(['Accept orders and expose status.','Serve product reads and stock checks.','Keep already-accepted work recoverable.'],['Illustrative peak: 1,000 requests/s, 80% reads.','Illustrative read p95 below 200 ms.','No duplicate order or negative inventory.','Continue after losing one application instance.'])+p('These are example targets, not universal defaults. Measure payload size, read/write mix, dependency fan-out, and burst duration. A peak lasting one second may be buffered; a peak lasting an hour needs sustainable service capacity. Distinguish offered traffic, admitted traffic, and successfully completed business work.')),
section('measure','Connect throughput, latency, and concurrency',p('Throughput counts completed work per unit time. Latency measures elapsed time for an operation. Concurrency counts work in progress. At steady state, Little’s Law relates averages: in-flight work ≈ arrival rate × average time in the system. At 1,000 requests/s and 0.2 s average response time, roughly 200 requests are in flight.')+p('That estimate does not set your thread-pool or database-pool size. Some requests wait without holding threads; one request can make several downstream calls; tail latency and bursts differ from averages. Measure queue wait separately from execution time so a fast handler does not hide an overloaded admission queue.')+code('Measure per route:\n  admitted/completed requests per second\n  p50 / p95 / p99 response time\n  active requests and queue wait\n  CPU, GC pauses, DB pool wait, dependency latency\n  rejection and retry rates')+p('A percentile describes a distribution: p99 of 800 ms means 99% of measured observations are at or below 800 ms for that window/population. Do not average per-instance percentiles to obtain a global percentile.')),
section('scaling','Vertical first, then horizontal when justified',table(['Choice','What changes','Constraint'],[['Vertical scaling','Give one instance more CPU/memory.','Simple but finite; failure domain remains large.'],['Horizontal scaling','Run more application instances.','State, shared dependencies and load distribution must support it.'],['Partitioning','Divide data/work by a key.','Cross-partition operations and hot keys become harder.']])+p('Horizontal scaling works best when any healthy instance can process a request. Keep durable order state in the database rather than a Java field. A local cache can still exist, but its contents may differ between instances. Sticky sessions can ease a migration; they do not make session state survive instance loss.')+diagram(['Clients','Load balancer','Stateless app fleet','Shared database'], 'The shared database remains a common constraint even after application replicas increase.')+p('A load balancer routes traffic; health checks determine eligible targets. Readiness should indicate that the instance can handle intended traffic, while liveness answers whether restarting may help. Marking every instance unready for a short shared dependency outage can amplify the outage.')),
section('implementation','Implement a bounded scaling change',p('In Spring Boot, configure bounded HTTP/dependency timeouts and monitor the data-source pool. With an ALB and ECS service, distribute tasks across appropriate failure domains and use target tracking on a metric related to useful load. In EKS, HPA changes pod replicas; node provisioning and scheduling are separate steps. Neither makes RDS write capacity infinite.')+code('Illustrative capacity guard:\n  8 app instances × 15 DB connections = 120 possible connections\n  Reserve DB headroom for operations, jobs, and failover.\n  Scaling to 20 instances without a pool policy → 300 connections.\n  Verify throughput under contention before increasing either limit.')+p('Use rolling delivery with graceful shutdown: stop admitting new requests, drain in-flight work, then terminate. Background workers need leases or queue acknowledgement rules so interrupted work can be reclaimed. Configure deployment surge and replica limits against shared-resource budgets.')+p('Autoscaling reacts after measurement and startup delay. Pre-scale known events and keep headroom where startup is slow. For queue workers, backlog per worker and oldest-message age may be better signals than CPU alone.')),
section('selection','Choose the next intervention',table(['Evidence','Intervention','Check afterward'],[['App CPU saturated; database has headroom','More/faster app compute, reduce expensive CPU work','CPU/request and latency under the same load.'],['Slow query dominates','Index/query/model correction','Query plan, lock time, write overhead.'],['Repeated read work','Cache or read model','Freshness contract and miss-path capacity.'],['Remote service limits','Concurrency cap, queue, negotiated quota','Queue age and completed outcomes.'],['One tenant/key dominates','Fair admission or split workload','Per-tenant impact and hot partition behavior.']])+warn('A cache hit rate of 95% does not prove resilience: if cache loss sends all reads to the database, the miss path may need 20 times its usual capacity. A read replica may help reads but introduces freshness and failover considerations.')),
section('worked','Worked design: twenty times the traffic',p('The baseline service sustains 100 requests/s. The target is 2,000. Profile first: product reads dominate and run the same indexed lookup; checkout writes are a small share. Cache public product descriptions with a documented freshness bound, keep stock/price validation authoritative at checkout, and separate admission budgets for browsing and purchase.')+p('Load-test the app fleet against a representative database. Increase replicas only while useful throughput improves. Apply a per-route concurrency cap to prevent the browsing surge from consuming every DB connection. Queue noncritical receipt work after a durable outbox commit. Keep the order command synchronous only to its bounded acceptance point.')+p('Test loss of one app instance and a cold cache at peak. If the database cannot sustain the cold path, limit refill concurrency, return permitted stale data or shed browsing load. Verify duplicate retries do not create extra orders. Success is meeting latency and correctness targets during these transitions, not reaching a replica count.')),
section('pitfalls','Tricky cases and operations',table(['Case','Why it happens','Response'],[['All replicas start together','Empty local caches and connection establishment spike','Stagger rollout; bound refill/connections.'],['CPU low, requests slow','Waiting for DB locks or remote connections','Inspect wait metrics and traces before scaling CPU.'],['Scale-in kills active work','Termination occurs before drain completes','Drain requests, reclaim durable jobs, test interruption.'],['Average latency looks fine','A small customer segment suffers extreme waits','Break down route/tenant cohorts without unbounded metric labels.']])+p('Keep a baseline cost per completed request. More replicas can increase cost while reducing throughput if contention dominates. Use a soak test to find memory leaks and backlog growth that a five-minute spike test misses.')),
section('interview','Interview ladder',qa([['Foundational','Latency versus throughput?','Latency measures time per operation; throughput measures completed work per time. High concurrency can raise throughput until contention makes both latency and efficiency worse.'],['Foundational','Does a load balancer make a service scalable?','It distributes traffic across targets. The targets and their shared dependencies must have capacity, and durable state must survive routing changes.'],['Intermediate','Why can HPA make a database incident worse?','More pods can create more connections and concurrent queries against the same constrained database. Bound shared-resource use and address the limiting query/lock before raising replicas.'],['Intermediate','How do you scale a stateful application?','Identify which state must survive instance loss. Move or replicate it with an appropriate ownership/durability model, or partition ownership deliberately. Routing affinity alone is not durable state management.'],['Advanced','How would you prove a 20× scaling claim?','Use representative data and load, explicit SLOs, steady-state and burst tests, failure injections, and correctness assertions. Report offered/admitted/completed work, saturation, and cost; record the first bottleneck.'],['Advanced','What if one key remains hot after sharding?','More shards do not split one unsplittable operation. Consider caching, aggregation, salting with merge semantics, a single-writer model, or a product limit, according to the invariant.'] ])),
section('references','Further reading and practice',refs([['https://docs.aws.amazon.com/elasticloadbalancing/latest/application/introduction.html','Application Load Balancer','routing and health-check behavior.'],['https://kubernetes.io/docs/tasks/run-application/horizontal-pod-autoscale/','Kubernetes HPA','replica control and stabilization.'],['https://docs.aws.amazon.com/autoscaling/application/userguide/target-tracking-scaling-policy-overview.html','AWS target tracking','metric selection and scaling behavior.']])+p('<strong>Exercise:</strong> map a service you know to demand, service time, shared-resource capacity and failure headroom. Name one improvement that would reduce work instead of adding machines.'))
]},
{
slug:'databases',title:'Databases',heading:'Choose storage by the questions and invariants it must serve',
intro:'Build an order store step by step: access patterns, keys, indexes, transactions, replication, and partitioning. Follow the data before choosing a database brand.',
definition:'A database manages durable data and supplies defined operations for reading and changing it. A data model describes entities, relationships and constraints; a storage engine and access paths determine how those operations are executed.',
prerequisites:'Know JSON objects and the basic meaning of an SQL table. Read <a href="index.html#requirements">requirements</a> and <a href="scalability.html#measure">workload measurements</a> if latency or throughput terms are unfamiliar.',outcome:'Select a storage model for an access pattern, explain its consistency boundaries, and diagnose the cost of a query or concurrent update.',
sections:[
section('problem','An order is more than a JSON document',p('The first order endpoint accepts a customer, items, and a total. Storing that JSON looks sufficient until the next requirements arrive: find recent orders for one customer, prevent two orders with the same external ID, reserve stock, and calculate daily revenue. These are different access patterns and correctness requirements.')+p('An access pattern is a specific question or mutation: “latest 25 orders for tenant T and customer C” is useful; “we need flexible queries” is too vague to choose an index. Write frequency, result size, ordering and freshness beside each pattern.')),
section('requirements','List operations and invariants',req(['Create order and line items.','Read one order; list recent orders for a customer.','Reserve stock and expose payment state.'],['No duplicate partner order within a tenant.','Stock must not become negative.','Illustrative p95 order lookup below 100 ms.','Durable accepted order; recovery point defined explicitly.'])+p('An invariant is a condition that must hold after every allowed transition. “Never negative stock” needs an atomic mutation; a fast eventual view is insufficient. “Revenue dashboard updated within a minute” can use an asynchronous projection. Different operations can therefore use different storage paths without changing the source of truth.')),
section('model','Keys and constraints before indexes',code('CREATE TABLE orders (\n  id uuid PRIMARY KEY,\n  tenant_id uuid NOT NULL,\n  external_id text NOT NULL,\n  customer_id uuid NOT NULL,\n  created_at timestamptz NOT NULL,\n  status text NOT NULL,\n  UNIQUE (tenant_id, external_id)\n);')+p('The primary key identifies a row. The unique constraint enforces one external order ID per tenant even when two requests race. Checking existence in Java first is useful for a friendly error but cannot replace the constraint. Relational foreign keys can enforce referenced identity; domain transitions still require application rules.')+p('Normalize when it protects shared facts and useful relationships. Embed or denormalize when an access pattern benefits and you can own the update rules. Duplicating customer display name into an order may preserve a historical snapshot; duplicating live account credit can create an invariant problem.')),
section('indexes','Derive an index from a query',code('SELECT id, created_at, status\nFROM orders\nWHERE tenant_id = :tenant AND customer_id = :customer\nORDER BY created_at DESC, id DESC LIMIT 25;\n\nCREATE INDEX order_customer_recent\nON orders (tenant_id, customer_id, created_at DESC, id DESC);')+p('An index is an additional access structure. The ordering above lets the engine locate a tenant/customer range and return recent rows without sorting the whole order table. It costs storage and work on inserts/updates. A low-selectivity index or incompatible leading columns may not help the actual query.')+p('Use EXPLAIN to inspect the plan; use EXPLAIN ANALYZE carefully because it executes the statement. Compare estimated and actual row counts, scanned rows, sorts and buffer activity with representative data. A sequential scan is sometimes the correct choice for a large fraction of a table.')),
section('transactions','What a transaction protects',p('A transaction groups operations into an atomic commit. Isolation controls which concurrent observations and anomalies are permitted. Under PostgreSQL Read Committed, each statement sees a snapshot from the start of that statement; two statements can see different committed data. Repeatable Read gives a stable transaction snapshot but does not make every business invariant automatic.')+code('BEGIN;\nUPDATE inventory SET available = available - :qty\nWHERE sku = :sku AND available >= :qty;\n-- Continue only if exactly one row changed; qty must be positive.\nINSERT INTO reservations (...);\nCOMMIT;')+p('In Spring, a transaction interceptor normally surrounds a proxied method invocation. Self-invocation can bypass proxy interception. Keep the data-source and transaction-manager relationship explicit, avoid long remote calls while holding locks, and understand rollback rules. Catching an exception does not necessarily make a failed transaction usable again.')+diagram(['Validate command','Conditional DB mutation','Store reservation + outbox','Commit or roll back'], 'The local transaction covers local writes. It does not include a remote payment provider.')),
section('models','SQL and NoSQL as access-model choices',table(['Model','Good fit','Boundary to examine'],[['Relational (PostgreSQL/RDS)','Relations, constraints, transactions, flexible indexed queries','Join/query cost, locks, write capacity.'],['Key-value (DynamoDB)','Known partition-key access and conditional item changes','Key distribution, secondary-index behavior, transaction scope.'],['Document (MongoDB)','Aggregate-shaped documents read/updated together','Document growth, multi-document invariants and index cost.'],['Search index','Relevance and text search','Projection freshness; not an automatic authority for orders.'],['Object storage (S3)','Large immutable blobs and exports','Object lifecycle and metadata/query service.']])+p('“NoSQL scales” is not a selection criterion. A badly chosen partition key can overload one partition. SQL databases can partition and replicate; NoSQL databases may offer transactions. State the specific operation, transaction boundary, consistency mode and operational cost.')),
section('replication','Replication and partitioning solve different problems',p('Replication keeps copies of data. A read replica can absorb reads but may lag behind the writer. If checkout writes an order and immediately reads a replica, the customer can see “not found.” Route that read to an appropriate authoritative path or offer a documented read-your-writes mechanism.')+p('Partitioning divides data across ranges or keys. It can distribute capacity, but now a cross-partition operation may require more coordination. Choose a key from access locality and load distribution together: tenant ID is convenient, yet one enormous tenant can remain hot. Backups are separate from replicas because a bad delete can replicate perfectly.')+p('For RDS, inspect the selected engine and deployment type: traditional Multi-AZ standby behavior differs from readable replicas and Multi-AZ DB cluster configurations. For DynamoDB, verify consistency support for the exact table/index and topology; do not assume every read path supports strongly consistent reads.')),
section('worked','Worked design: order store and revenue view',p('Keep orders, reservations and outbox in the relational write model because stock and duplicate-order rules need local atomicity. Use the customer/recent index for customer pages. Publish committed outbox changes to an analytics projection keyed by date and merchant. The dashboard can be one minute behind; order acceptance cannot depend on its freshness.')+p('Each projection update carries an event identity or source position so replay does not double revenue. If order states can change, the projection must handle corrections/refunds, not just increment on every event. Backfill from a consistent snapshot plus a change position or an equivalent reconciliation strategy so concurrent changes are neither lost nor counted twice.')+p('Test unique-key races, concurrent last-item purchases, replica lag after create, transaction deadlocks, and projection replay. Observe pool waits, query latency, locks, slow-query plans and replica lag. Adding an ORM does not remove database behavior: JPA flush timing and N+1 queries still need measurement.')),
section('pitfalls','Tricky failures to rehearse',table(['Failure','Common mistake','Better response'],[['Replica lag after write','Treat a missing replica row as a failed creation','Use authoritative lookup and retry identity.'],['Schema rollout','New writer breaks old readers during rollback','Expand, migrate, verify, then contract.'],['Hot partition','Add partitions without changing skew','Measure key distribution and choose a split/aggregation policy.'],['Backup exists','Assume recovery is proven','Restore into isolation and measure recovery time/data loss.']])+p('Record recovery time objective (RTO: acceptable recovery duration) and recovery point objective (RPO: acceptable data-loss window). Availability of a running replica is not the same as recoverability after corruption or an operator mistake.')),
section('interview','Interview ladder',qa([['Foundational','Primary key versus index?','A primary key identifies a row and enforces uniqueness/non-null semantics. An index is an access structure; databases commonly implement key constraints with indexes, but not every index defines identity.'],['Foundational','Does an index always make a query faster?','No. Selectivity, column order, result size, data distribution and plan choice matter. Indexes also increase write and storage cost.'],['Intermediate','Why is check-then-insert unsafe?','Two transactions can both observe absence before either commits. A unique constraint or equivalent atomic conditional operation is the final concurrency guard.'],['Intermediate','Can a read replica show stale data?','Yes when replication is asynchronous or the selected read path lags. Define freshness requirements and route operations accordingly.'],['Advanced','How do you migrate without a write outage?','Choose an initial consistent copy plus change capture/catch-up and verification, control the write switch, define rollback and conflict ownership, and test failure windows. The exact protocol depends on source/target capabilities.'],['Advanced','When would you avoid a distributed transaction?','When a durable state machine, outbox and compensation can meet the business contract with less coordination. That introduces temporary intermediate states and recovery work rather than making cross-system atomicity disappear.'] ])),
section('references','Further reading and practice',refs([['https://www.postgresql.org/docs/current/transaction-iso.html','PostgreSQL isolation','statement snapshots, anomalies and retry requirements.'],['https://www.postgresql.org/docs/current/using-explain.html','PostgreSQL EXPLAIN','read real query plans before optimizing.'],['https://docs.spring.io/spring-framework/reference/data-access/transaction.html','Spring transactions','proxy boundaries and transaction behavior.'],['https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/HowItWorks.ReadConsistency.html','DynamoDB read consistency','table/index-specific guarantees.']])+p('<strong>Exercise:</strong> write three access patterns for your service, derive one index, and identify one invariant that belongs in a constraint or conditional write.'))
 ]},
{
slug:'caching',title:'Caching',heading:'Make repeated reads cheaper without hiding the truth',
intro:'Start with one repeated product lookup. Build a cache, then follow what happens when data changes, entries expire together, or the cache disappears.',
definition:'A cache stores a reusable copy of data or computation to reduce the cost of retrieving it again. The source of truth remains authoritative; cache design defines identity, freshness, eviction and failure behavior for the copies.',
prerequisites:'Know a database lookup and an HTTP response. <a href="databases.html#indexes">Indexes</a> reduce lookup cost without creating an application cache; understand that distinction first.',outcome:'Choose a read/write pattern, define freshness and isolation, and protect the source during a cache incident.',
sections:[
section('problem','Why repeat the same read?',p('Every product-page request reads the same description from SQL. The query is indexed, but a popular product still generates thousands of identical reads. A copy kept near the caller avoids repeating network and database work. That is the opportunity a cache addresses.')+p('Now a merchant changes the description. The database is correct immediately; the copy may not be. Caching exchanges repeated-work cost for ownership of copy freshness. Before choosing Redis, ask how stale the product page may be and whether checkout must use the same answer. A five-minute-old description may be acceptable; a five-minute-old permission or stock decision may not be.')),
section('requirements','Define the freshness contract',req(['Read product details and update them as a merchant.','Share popular data across application instances.','Return a controlled response when a cache read fails.'],['Illustrative display staleness: at most 60 seconds under the stated policy.','Never reuse one tenant’s private representation for another.','Checkout revalidates authoritative price/stock.','Cache loss must not overload the database.'])+p('A TTL by itself is not necessarily a bound on staleness relative to the latest write: a slow reader can refill an old value after invalidation. State which races and refresh failures your guarantee covers. If an invariant requires current data, enforce it at the authoritative mutation path.')),
section('read-pattern','Walk through cache-aside',p('Cache-aside means the application first checks the cache, reads the source on a miss, then fills the cache. A hit returns the copy. A miss is normal—it is not an error—and must have a working bounded path.')+diagram(['Cache lookup','Miss only: query source','Fill with TTL'], 'A hit returns immediately and skips the source/fill path. A miss fills after reading the source; that interval can race with writers.')+code('Product getProduct(TenantId tenant, ProductId id) {\n  String key = "product:v2:" + tenant + ":" + id;\n  Product cached = cache.get(key);\n  if (cached != null) return cached;\n  Product value = repository.find(tenant, id);\n  cache.put(key, value, Duration.ofSeconds(60));\n  return value;\n}\n// Teaching pseudocode: add timeouts, missing values, failure policy and metrics.')+p('Include every dimension that changes the reusable value: tenant, locale, currency, schema version or permission scope where relevant. Avoid using raw credentials as keys. A user-specific representation often belongs in a private or per-user cache rather than one shared product key.')),
section('write-pattern','What happens after a write?',p('The simplest policy is commit the authoritative update, then delete the cached copy. Next read repopulates it. If deletion fails after the DB commit, the old entry can survive until expiry; an outbox-driven invalidation can make retries durable. It still requires a policy for reads racing with the write.')+code('Race to reason about:\n1. Reader misses and reads DB version 7.\n2. Writer commits version 8, then deletes cache key.\n3. Reader finishes late and caches version 7.\n4. New readers temporarily see version 7 again.')+p('Options include tolerating bounded staleness, caching under immutable/versioned keys, and using version-aware conditional publication tied to durable version knowledge. A compare-and-set only against an existing cache value does not solve the absent-key race unless the protocol preserves a newer version marker. “Delete twice after a delay” reduces some races but is not a general proof of consistency.')+table(['Pattern','Useful when','Cost'],[['Cache-aside','Read-heavy data; misses are acceptable','Stale copies and refill races.'],['Write-through','Writes go through a component that updates cache/source','Failure ordering and authority must be explicit.'],['Write-behind','Buffering asynchronous persistence is acceptable','Loss/durability and ordering become core requirements.'],['No cache on decision path','Current state determines permission or stock','More source work, but clearer invariant.'] ])),
section('layers','Local, distributed, and edge caches',p('A Caffeine local cache avoids a network hop, but each Java process holds its own copy. Redis/Valkey provides a shared remote cache, adding network latency, serialization and an operational dependency. A CDN such as CloudFront caches HTTP representations near readers; HTTP cache headers and key policy decide reuse.')+p('These layers can coexist, but their freshness periods can compound. Inspect the age/source version instead of assuming the shortest TTL controls every layer. Redis persistence or replicas can improve recovery, but a cache replica is not automatically the authoritative database. Decide whether the cache is disposable; if it holds unique business data, you have designed a data store with different durability requirements.')+p('<strong>Spring mapping:</strong> the cache abstraction can use a local or Redis-backed CacheManager. With proxy-based caching, self-invocation does not pass through the interceptor. Choose cache names, key generation, serialization and TTL in provider configuration rather than assuming the annotation defines them all.')+code('@Cacheable(cacheNames = "products", key = "#tenant + \':\' + #id")\npublic ProductView load(String tenant, String id) {\n  return repository.loadView(tenant, id);\n}\n// Provider config supplies expiry/serialization; invoke through the Spring proxy.')),
section('capacity','Expiration, eviction, and stampedes',p('Expiration makes an entry ineligible after time. Eviction removes entries to satisfy capacity policy. Neither is a business deletion notification. Size the working set from key count, key/value bytes, metadata overhead and replication; test with realistic serialization rather than payload size alone.')+p('A stampede occurs when many requests miss the same key and all refill it. Collapse same-key work locally, use bounded distributed coordination when necessary, and add expiry jitter so many keys do not expire together. Coordination locks need leases and failure rules; do not hold a global lock around every product lookup.')+p('Negative caching stores “not found” briefly to suppress repeated misses. Use a distinct marker and short policy, and avoid turning temporary database failure into a cached “not found.” Hot-key pressure can remain even with many cache shards because one key still has one primary ownership path.')),
section('worked','Worked design: catalog during a flash sale',p('Product descriptions are cacheable for 60 seconds; prices shown in browse responses are indicative; checkout uses the current authoritative pricing rule. Use CloudFront for public media, Redis for shared product views and a small local cache only if its additional staleness is acceptable. Put tenant and locale in the key, and keep personalized discounts separate.')+p('Merchant update commits to SQL with an outbox invalidation event. The invalidator retries failed deletes. Refill uses per-key work collapse and a database concurrency budget. On a cache outage, permit a limited miss-path load; serve an allowed stale display copy or reject nonessential reads after the budget is exhausted. Never allow every request to bypass the failed cache simultaneously.')+p('Observe hit/miss rate together with source load, fill latency, entry age/version, eviction, memory and cache error rate. Test a cold start at peak, invalidation delayed behind a slow reader, one hot product, tenant-key mistakes and cache timeouts. Verify checkout rules independently of page freshness.')),
section('pitfalls','Tricky cases and recovery',table(['Case','Risk','Policy'],[['Redis unavailable','All traffic falls through to SQL','Bound fallback; shed noncritical reads.'],['Serializer changes','Old values cannot be decoded','Version key/value format; roll safely.'],['Permission revoked','Old cached authorization still allows access','Enforce sensitive checks authoritatively or design an explicit revocation bound.'],['Delete notification lost','A consumer assumes every expiration is observed','Use a durable event mechanism for required business work.']])+warn('Redis keyspace notifications are not a durable business-event log. A disconnected subscriber can miss notifications. Use them for suitable best-effort observations, not as the only proof that an order must be processed.')),
section('interview','Interview ladder',qa([['Foundational','Cache hit versus miss?','A hit finds a reusable eligible value; a miss requires another source or a controlled fallback. Miss performance matters during normal expiry and incidents.'],['Foundational','TTL versus eviction?','TTL is time-based eligibility; eviction is capacity-policy removal. Entries can be evicted before TTL. Neither guarantees a reliable deletion event.'],['Intermediate','Why delete after DB commit rather than before?','Deleting first lets a concurrent reader refill the old DB value before the write commits. Deleting after commit avoids that specific ordering, but a late reader can still refill old data, so state the remaining race.'],['Intermediate','Would you cache account permissions?','Only with a documented revocation/freshness policy and suitable isolation. For a sensitive mutation, use authoritative validation or a protocol that enforces the required revocation bound.'],['Advanced','How do you survive loss of a 99% hit-rate cache?','The source may see up to 100 times usual miss traffic. Use bounded fallback/refill, headroom, permitted stale responses, admission control and recovery tests.'],['Advanced','Does a distributed lock solve consistency?','It only coordinates participants that obey it during its valid lease. Expiry, stale holders, crashes and outside writers remain; durable version/invariant enforcement may still be required.'] ])),
section('references','Further reading and practice',refs([['https://docs.spring.io/spring-framework/reference/integration/cache.html','Spring cache abstraction','proxy semantics and provider responsibilities.'],['https://redis.io/docs/latest/develop/use/keyspace-notifications/','Redis keyspace notifications','delivery limitations and event configuration.'],['https://redis.io/docs/latest/develop/reference/eviction/','Redis eviction','memory policy and eviction behavior.'],['https://www.rfc-editor.org/rfc/rfc9111','HTTP caching','freshness and validation for edge/client caches.']])+p('<strong>Exercise:</strong> draw a cache refill racing with an update. State exactly how long stale data can persist and what evidence supports that bound.'))
]},
{
slug:'messaging',title:'Messaging',heading:'Move work asynchronously and own every delivery boundary',
intro:'Begin with a slow receipt email in checkout. Learn queues and event logs, acknowledgements, duplicates, ordering, outbox/inbox patterns, and operational recovery.',
definition:'Asynchronous messaging transfers commands or events through an intermediary so production and consumption need not complete in the same request. Delivery guarantees describe a particular boundary; they do not automatically describe the business effect.',
prerequisites:'Understand the <a href="databases.html#transactions">local transaction boundary</a> and the <a href="index.html#reliability">uncertainty after an HTTP timeout</a>. A broker is simply the service holding messages between producer and consumer.',outcome:'Design a durable producer-to-consumer flow and explain what happens after a crash before or after acknowledgement.',
sections:[
section('problem','Remove email from the checkout wait',p('Checkout commits an order, calls an email provider, then returns. When email slows, purchase latency grows even though the order is already stored. Sending an email is important but usually does not have to finish before confirming order acceptance. We can record work and let another process do it later.')+p('Moving the call into an in-memory background thread shortens the request but loses the task when the process dies. A durable queue stores the task independently. That buys time decoupling and burst buffering; it also creates a new question: who knows whether the work finished?')),
section('requirements','Define acceptance and completion separately',req(['Accept an order and schedule receipt work.','Allow fulfillment and analytics to react independently.','Retry transient delivery errors and recover failed work.'],['No lost receipt intent after order commit.','Duplicate delivery must not duplicate protected business effects.','Illustrative oldest receipt age under two minutes.','One broken message must not block all healthy work.'])+p('A command asks someone to act, such as SendReceipt. An event records a fact, such as OrderAccepted. Events often have several independent consumers. Commands should have clear ownership; events should carry enough identity and contract information for consumers to interpret them safely.')),
section('models','Queue versus retained event log',table(['Model','Reader behavior','Use'],[['Work queue','Workers compete for tasks; successful processing removes/acknowledges work','Jobs and independently retried commands.'],['Publish/subscribe','Each subscription gets its own delivery path','Several independent reactions to an event.'],['Partitioned log','Consumers track positions; records are retained by policy','Replay, ordered per-partition streams, projections.']])+p('In Kafka, a consumer group normally divides partition ownership among its members; different groups can independently consume the same retained records. Parallelism within one group is constrained by partitions and assignment. In SQS standard queues, consumers compete and delivery can repeat; ordering is best-effort. FIFO adds specific ordering/deduplication semantics, not automatic atomicity with your database.')+diagram(['Order + outbox commit','Relay to broker','Consumer local transaction','Ack / commit position'], 'Every arrow is a failure boundary. Follow the stable event identity through all of them.')),
section('ack','Walk through the acknowledgement window',p('A consumer receives a message, writes a shipment, and then acknowledges it. If it crashes after the shipment commits but before acknowledgement, the broker may redeliver. Acknowledging first has the opposite risk: the task can disappear before the shipment exists. Neither ordering alone gives one business effect.')+code('Safe local-effect pattern:\nBEGIN;\nINSERT INTO inbox(consumer, event_id) VALUES (...)\n  ON CONFLICT DO NOTHING;\n-- If already present, skip the effect and acknowledge.\n-- Otherwise apply local domain mutation in this transaction.\nCOMMIT;\nACK message / commit consumed position afterward;')+p('The inbox uniqueness constraint and local mutation must share the same commit. A remote shipment provider remains outside that transaction; it needs its own retry identity/status lookup or reconciliation. Retain deduplication records long enough for the replay/redelivery horizon. Deleting them early permits old events to act again.')),
section('outbox','Close the producer dual-write gap',p('Saving an order and sending a message are two separate writes. DB first can leave an order without an event when the process crashes. Broker first can publish an event for an order that later rolls back. An outbox records the order and an event row in one local transaction; a relay publishes committed rows afterward.')+code('@Transactional\npublic Order accept(CreateOrder cmd) {\n  Order order = orders.insert(cmd);\n  outbox.insert(new Event(order.id(), "OrderAccepted", 1));\n  return order;\n}\n// Relay publishes committed rows; publish success and "sent" marking can race.\n// Expect duplicate publication and keep eventId stable.')+p('Spring transaction management can cover the local database work. A Spring Kafka or AWS SDK producer sends from the relay. Broker transactions have useful scopes, but do not assume an annotation atomically commits PostgreSQL, Kafka, SQS and a provider. Verify the exact transaction boundary for the chosen client/infrastructure.')),
section('ordering','Ordering, schema evolution, and replay',p('Choose an ordering key from the business aggregate: orderId groups one order’s events. Global ordering can become a throughput constraint and is often unnecessary. Even if the broker preserves partition order, retries and asynchronous side effects can finish out of order unless the consumer coordinates them.')+p('Include eventId, event type, schema version, aggregate ID/version, occurred-at time and payload. Event time is when the business fact happened; processing time is when a consumer handles it. A later-arriving event can describe an earlier fact. Use version guards or explicit state transitions rather than blindly overwriting current state.')+p('Replay is a feature only if effects are safe. Rebuilding a search projection should not resend every receipt email. Separate replayable projections from external effects, preserve deduplication identity, and design schema readers for retained old data.')),
section('implementation','SQS and Kafka operational choices',table(['Concern','SQS-style work queue','Kafka-style log'],[['Progress','Message acknowledgement/deletion and visibility','Consumer position/offset by partition.'],['Slow consumer','Visibility can expire; extend appropriately','Poll/processing and group timeouts need correct tuning.'],['Retry','Redelivery, delayed queues, DLQ policy','Retry topics or controlled retry; ordering trade-offs.'],['Replay','Explicit retained source/archive strategy','Reset positions while records remain retained.']])+p('SQS visibility timeout is a lease-like hiding period, not exclusive ownership forever. A second worker may receive the message when it expires. Bound processing time, extend visibility when appropriate, and keep effects idempotent anyway. Kafka lag counts how far a consumer is behind; also measure oldest-event age and actual processing failures.')+p('A poison message fails repeatedly because of its data or a deterministic bug. After a bounded policy, quarantine it with diagnostics and ownership. A DLQ is not resolution: operators need a fix, replay authorization, and proof the replay cannot duplicate earlier effects.')),
section('worked','Worked design: fulfillment after checkout',p('Checkout commits order plus OrderPaid outbox when payment is confirmed. A relay publishes the stable event. Fulfillment workers record an inbox row and create a local fulfillment task atomically, then acknowledge the event. A separate task runner calls the warehouse with a stable fulfillment identity and stores the warehouse reference.')+p('If the warehouse times out after accepting the shipment, the task is UNKNOWN rather than failed. Query the original reference or use a provider retry contract before resubmitting. Analytics uses a separate subscription/group so a slow dashboard does not block shipping. Receipt email has its own retry and deduplication policy, with any residual duplicate-mail risk made explicit.')+p('Test process death after DB commit/before publish, after publish/before sent-mark, after consumer effect/before ack, and after provider acceptance/before response. Add duplicate, delayed, out-of-order and old-schema events. Assert fulfillment identity and state, not merely queue depth.')),
section('pitfalls','Backpressure and recovery',p('A queue hides a short burst; it cannot fix permanent undercapacity. If arrivals exceed completions, oldest-message age rises even while producers return quickly. Scale workers only within downstream capacity, and use tenant fairness or priorities carefully so one backlog does not starve critical work.')+warn('“Exactly once” always needs a scope. Kafka transactional processing can atomically coordinate supported Kafka operations/positions under the configured model; it does not make an arbitrary email or SQL mutation exactly once. State the boundary and prove the effect separately.')),
section('interview','Interview ladder',qa([['Foundational','Why use a queue?','To decouple timing, persist pending work and buffer bursts. It introduces delayed completion, consumer operations and delivery semantics.'],['Foundational','Command versus event?','A command asks for an action and has an owner; an event describes a fact that can have independent consumers.'],['Intermediate','Why acknowledge after commit?','Acknowledging first risks losing work if the commit never happens. Commit first can cause redelivery, so make the effect idempotent through a shared local transaction or another appropriate protocol.'],['Intermediate','What does an outbox guarantee?','The local business change and pending event are committed together. Publication can repeat, so consumers still need safe duplicate handling.'],['Advanced','How do you rebuild a projection safely?','Use retained events/snapshot plus a consistent change position, handle versions, isolate rebuild traffic and suppress external business effects. Verify completeness against the source.'],['Advanced','What if FIFO messages still create duplicates?','Send deduplication, visibility and redelivery are different boundaries. Protect the consumer effect with stable business identity, conditional transitions and appropriate retention.'] ])),
section('references','Further reading and practice',refs([['https://docs.aws.amazon.com/amazonsqs/latest/SQSDeveloperGuide/standard-queues-at-least-once-delivery.html','SQS at-least-once delivery','why consumers must tolerate repeats.'],['https://docs.aws.amazon.com/amazonsqs/latest/SQSDeveloperGuide/sqs-visibility-timeout.html','SQS visibility timeout','processing leases and redelivery.'],['https://kafka.apache.org/documentation/','Apache Kafka documentation','partitions, consumer groups and transaction semantics.'],['https://docs.spring.io/spring-kafka/reference/','Spring for Apache Kafka','listener acknowledgement, error handling and transactions.']])+p('<strong>Exercise:</strong> mark each commit/ack in a flow you own. At every gap, kill the process in a test and explain the recovery identity.'))
]},
{
slug:'reliability',title:'Reliability',heading:'Keep useful work recoverable when dependencies fail',
intro:'Follow a checkout request through slow services, lost responses and process crashes. Derive deadlines, retries, idempotency, circuit breakers and recovery from those failures.',
definition:'Reliability is the ability to perform the required function correctly over time under stated conditions. Availability concerns whether the service can be used; recoverability concerns restoring correct operation and data after failure.',
prerequisites:'Understand an <a href="index.html#contract">API contract</a>, <a href="databases.html#transactions">local transactions</a>, and <a href="messaging.html#ack">acknowledgement windows</a>. We introduce each resilience mechanism before combining them.',outcome:'Assign retry and recovery ownership without confusing a timed-out request with a rolled-back business action.',
sections:[
section('problem','A slow provider consumes the whole service',p('Checkout calls a pricing service and a payment provider. Usually both are fast. One morning the provider takes 30 seconds. Request threads and connections accumulate, queues grow, and eventually healthy status reads also fail. The first failure was remote slowness; the second was allowing that slowness to consume all local resources.')+p('A distributed call has several outcomes: succeeded, definitely rejected, or unknown. If the response is lost after a capture, the caller cannot infer that capture failed. Recovery starts by representing uncertainty honestly rather than retrying every exception as a new business action.')),
section('requirements','Identify what must remain correct',req(['Accept checkout, expose payment status and reconcile uncertain attempts.','Keep status reads usable during provider problems.','Let operators recover failed/unknown work safely.'],['One capture per payment intent under the provider protocol.','Illustrative p95 status read below 200 ms.','Bound dependency concurrency and queue length.','Explicit RTO/RPO and durable intent retention.'])+p('An SLO is a measurable reliability target over a window. An invariant is a condition that must hold, such as not shipping an unpaid order. A fallback can preserve availability while violating an invariant if chosen carelessly. Serving a stale product description can be acceptable; fabricating payment success cannot.')),
section('deadlines','First bound waiting time',p('A timeout bounds one wait. A deadline bounds the total useful time remaining for the request. Give downstream calls a share of the remaining budget, including connection acquisition, retry delay and response processing. A 500 ms client timeout with a 30-second backend call wastes work after the client has gone.')+code('Example 800 ms total budget:\n  validation/admission: 50 ms\n  provider + any allowed retry: at most 500 ms\n  persistence/response: 150 ms\n  safety margin: 100 ms\nDo not reset to a fresh 800 ms at every downstream hop.')+p('Configure connect, pool-acquisition and response/read timeouts for the actual HTTP client. Cancellation may interrupt local waiting without stopping remote work. A timeout cannot roll back an already-committed provider action. Use durable state and status lookup to resolve it.')),
section('retries','Retry an identity, not a new intent',p('A retry repeats an attempt because an earlier attempt did not produce a definitive outcome. Use it for selected transient failures only when repetition is safe. Exponential backoff spaces attempts; jitter spreads clients so they do not all retry on the same clock tick.')+p('Set a maximum attempt count, total elapsed deadline and retry budget. A budget limits the extra load retries can create. If the gateway, application and SDK each make three attempts, a request can fan out to 27 leaf attempts. Pick an owner and account for other layers explicitly.')+p('For a payment, persist a business intent and pass the same provider identity across retries if supported. Scope the client key by tenant/operation and reject a changed payload. Key retention must cover the replay horizon. A new random key per retry makes every attempt look like new intent.')+diagram(['Persist intent','Call with stable identity','Known outcome: store result','Unknown: reconcile'], 'Reconciliation queries or receives evidence about the original attempt; it is not another blind charge.')),
section('isolation','Add circuit breaking and bulkheads',table(['Mechanism','Meaning','What it does not do'],[['Circuit breaker','Temporarily stop calls after evidence of dependency trouble; probe recovery','It does not make a command idempotent.'],['Bulkhead','Limit resources assigned to one dependency/work class','It does not increase downstream capacity.'],['Rate limiter','Bound arrivals over time','It does not necessarily bound concurrent slow work.'],['Bounded queue','Limit waiting work and expose overload','It does not solve sustained excess demand.']])+p('Circuit breakers usually move among closed, open and half-open states. Half-open probes should be bounded; releasing every waiting caller when one probe succeeds can overwhelm a recovering dependency. Choose thresholds from real traffic, not arbitrary defaults.')+p('Separate payment-call concurrency from status-read resources. Reject early with a documented response when a budget is exhausted. Keep fallback behavior visible in metrics; a service can report 200 while returning unusable substitute data.')),
section('implementation','Spring and AWS implementation boundaries',p('Resilience4j offers independent retry, circuit-breaker, bulkhead and rate-limiter components. Decorator order changes what is counted and retried: ask whether the breaker sees every attempt or one logical call. Test the actual configuration rather than assuming a list of annotations composes correctly.')+code('// Teaching pseudocode: explicit semantic order, not a library API signature.\nrequireRemainingDeadline();\nreturn boundedPaymentConcurrency.execute(() ->\n    retryBudget.executeSafeAttempts(() ->\n        breaker.call(() -> provider.capture(stableIntentId, request))));\n// HTTP client timeouts and durable UNKNOWN-state recovery remain separate.')+p('Use Spring transaction management for durable intent and outcome updates, with remote calls outside long-held DB transactions. RDS holds the ledger; SQS can schedule retry/reconciliation work; Step Functions can coordinate explicit states when its execution model fits. ALB/API Gateway limits and SDK retry policies must be included in the end-to-end budget.')+p('A multi-AZ deployment addresses a failure domain; it does not protect against a bad release, corrupt writes or region-wide dependency failure. Test backup restoration and failover routing, and define who can initiate recovery.')),
section('worked','Worked design: provider outage during checkout',p('Persist a payment attempt as PENDING and expose its status resource. A worker calls the provider with the stable attempt identity. Success becomes SUCCEEDED; a definitive decline becomes DECLINED; transport ambiguity becomes UNKNOWN. A reconciler queries the provider or handles authenticated callbacks. Each transition is conditional so stale callbacks cannot overwrite a later terminal outcome.')+p('While the breaker is open, accept durable intents only if the product permits delayed processing and capacity is available; otherwise reject before promising acceptance. Show “payment processing” to the customer, never “paid” based on a timeout fallback. Status reads remain on a protected local path.')+p('Recovery is paced. Limit reconciliation concurrency and prioritize old unknown attempts. Compare local and provider records, quarantine discrepancies, and retain operator evidence. The warehouse acts only on a durable paid transition through an outbox. Replaying a recovery task must not create another payment or shipment.')),
section('pitfalls','Failure drills and recovery evidence',table(['Drill','Assertion'],[['Kill worker immediately after provider capture','Attempt becomes resolvable with original identity.'],['Provider stays slow for an hour','Pools/queues stay bounded; status reads remain usable.'],['Duplicate success after refund','Conditional state/version policy prevents regression.'],['Breaker recovers at traffic peak','Probe and release policy avoids a new surge.'],['Restore ledger backup','Measured RPO/RTO meet the declared recovery contract.']])+p('Track timeout rate, attempt count, retry amplification, breaker state, rejected concurrency, oldest unknown age and business discrepancy count. A green CPU chart is insufficient if payments remain unknown for hours.')),
section('interview','Interview ladder',qa([['Foundational','Timeout versus failure?','A timeout means the caller did not receive a result in time. The remote side effect may have completed, so classify the outcome as unknown when appropriate.'],['Foundational','Circuit breaker versus retry?','Retry performs another attempt. A circuit breaker suppresses attempts when a dependency appears unhealthy and probes for recovery. Their composition must not amplify overload.'],['Intermediate','Why use both a rate limit and a concurrency cap?','A rate limit bounds arrivals per time; slow operations can still accumulate. A concurrency cap bounds simultaneous resource use.'],['Intermediate','What makes a fallback safe?','Its result and side effects must preserve the operation’s business contract. Stale display data can be acceptable; invented payment success is not.'],['Advanced','What if the provider has no key or status inquiry?','Local coordination cannot prove a single remote effect across arbitrary lost-response windows. Require a stronger protocol or explicitly accept bounded retry/manual-settlement risk.'],['Advanced','How do you prevent recovery from causing another outage?','Bound probes, retry/reconciliation rate, queue drains and concurrency. Keep resource headroom and separate critical paths, then test a prolonged outage and synchronized recovery.'] ])),
section('references','Further reading and practice',refs([['https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/','AWS Builders’ Library: retries','timeout budgets and retry amplification.'],['https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/','AWS Builders’ Library: idempotency','caller intent and uncertain outcomes.'],['https://resilience4j.readme.io/docs/circuitbreaker','Resilience4j circuit breaker','states, thresholds and interaction with other mechanisms.'],['https://grpc.io/docs/guides/deadlines/','gRPC deadlines','deadline propagation and cancellation.']])+p('<strong>Exercise:</strong> identify one remote write you call. Write a recovery action for the exact moment after the remote commit but before your local outcome is saved.'))
]},
{
slug:'observability',title:'Observability',heading:'Explain what happened to one request and one business outcome',
intro:'Start with a customer asking where an order went. Build a useful evidence trail from logs to metrics, traces, asynchronous work, audit records and actionable alerts.',
definition:'Observability is the ability to infer a system’s internal behavior from its emitted evidence. Logs describe events, metrics summarize measurements, traces connect timed operations, and audit records preserve accountable business/security actions.',
prerequisites:'Know the <a href="index.html#contract">request contract</a> and <a href="messaging.html#ack">asynchronous delivery boundary</a>. No monitoring platform is assumed; the lesson defines the signals before naming tools.',outcome:'Trace a customer outcome across HTTP, SQL and messaging without leaking secrets or creating unbounded telemetry cost.',
sections:[
section('problem','The endpoint is green, but the customer has no order',p('A customer saw “accepted,” but fulfillment never arrived. The HTTP dashboard shows 99.9% success because the endpoint returned 202. That only measures acceptance. A consumer may be stuck, a message may be quarantined, or a payment may be unknown. Start from the business outcome and ask which evidence connects each stage.')+p('Without shared identity, engineers search timestamps in several services and guess which events belong together. Adding more text logs can make this harder. Useful observability begins with explicit operations, state transitions and correlation fields.')),
section('requirements','Decide the questions evidence must answer',req(['Find an accepted order and its current lifecycle state.','Locate latency/error causes across services and workers.','Audit who changed a sensitive business state.'],['No credential/card payload in telemetry.','Bound metric cardinality and storage cost.','Illustrative accepted-to-fulfilled SLO measured separately from HTTP.','Essential audit evidence survives trace sampling.'])+p('A service-level indicator (SLI) is the actual measurement, such as the fraction of eligible orders completed within five minutes. An SLO is the target for that measurement. Specify eligible events, time windows, missing evidence and where timestamps come from. Otherwise teams can appear reliable by dropping failed requests from the denominator.')),
section('signals','Use the right signal for each question',table(['Signal','Good question','Limitation'],[['Metrics','Is error rate rising? How old is the backlog?','Aggregates do not reconstruct every request.'],['Logs','What error/state transition was recorded?','Unstructured text and missing context make joins difficult.'],['Traces','Where did elapsed time go across this path?','Sampling or missing propagation can leave gaps.'],['Audit records','Who approved this refund and what changed?','Need deliberate integrity, access and retention policies.']])+p('A span is one timed operation in a trace, such as an HTTP handler or database call. Parent/child relationships explain a call path. Metrics summarize populations; labels split those populations into dimensions. A trace ID belongs in a log field or exemplar, not a metric label that creates one series per request.')),
section('identity','Separate request, trace, and business identity',code('{\n  "service": "checkout", "route": "/orders/{id}",\n  "requestId": "req_82", "traceId": "trace-example",\n  "orderId": "ord_7", "eventId": "evt_91",\n  "operation": "payment.confirm", "outcome": "SUCCEEDED",\n  "durationMs": 42\n}')+p('Request ID identifies one ingress attempt; trace context connects observed execution; order/payment/event identity identifies durable business work. A retry may have a new request/trace while acting on the same payment intent. Using trace ID as an idempotency key confuses these different lifetimes.')+p('W3C traceparent carries standard trace context between HTTP services. It is metadata, not authentication. Validate untrusted incoming context and apply your sampling policy. Do not accept a client-provided tenant or actor as authoritative simply because it is in a header.')+diagram(['HTTP server span','Outbound HTTP / SQL spans','Queue carrier metadata','Consumer processing span'], 'Cross-process context needs injection/extraction. Message identity remains durable even when a trace is not retained.')),
section('java-context','Java context and structured logging',p('MDC is a logging-framework context map, commonly tied to the current thread. A value put on the request thread does not automatically reach an executor task or reactive callback. Thread pools can leak old values if cleanup is missing. Use framework/instrumentation-supported propagation and restore/clear context in the correct scope.')+code('// Illustrative synchronous logging scope; use your logging API correctly.\nMDC.put("requestId", validatedOrGeneratedId);\ntry {\n  handler.process();\n} finally {\n  MDC.remove("requestId");\n}\n// This alone does NOT propagate context to another thread or message.')+p('OpenTelemetry Context provides execution-scoped trace propagation abstractions; Spring Boot Micrometer Tracing integrates with supported instrumentation. Use configured HTTP client builders/instrumentation so outbound context is injected. Verify executor, Reactor and messaging boundaries explicitly.')+p('Java ScopedValue provides lexically scoped immutable context binding in supported Java versions, useful for deliberate request-context design. It is not a logging adapter or distributed propagation protocol. MDC integration, instrumentation and task-boundary behavior still require an explicit strategy; do not assume replacing ThreadLocal changes every library.')),
section('metrics','Build metrics that stay affordable',p('Start with request rate, error rate, latency distribution and resource saturation. Add business indicators: accepted/completed orders, oldest unknown payment and oldest unprocessed event. A queue with ten messages can be worse than one with a thousand if the oldest critical message is hours old.')+p('Use bounded labels such as service, route template, method and outcome class. Raw URL, customer ID, order ID and exception text can generate unbounded series. Histogram bucket choices affect percentile estimates; choose them around relevant latency targets and aggregate compatible distributions, not per-pod percentiles.')+table(['Measurement','Useful interpretation'],[['HTTP latency + DB pool wait','Distinguish slow execution from waiting for a connection.'],['Accepted-to-completed duration','Capture asynchronous user experience.'],['Retry attempts / original commands','Detect amplification hidden by final success.'],['Outbox age / DLQ count','Find durable work that is not progressing.']])+p('Sampling can keep traces affordable, but head sampling may miss rare errors and tail sampling has buffering/collector cost. Keep essential operational metrics and required audit outcomes independently of sampled traces.')),
section('implementation','Spring and AWS instrumentation map',p('Spring Boot Actuator and Micrometer expose application/HTTP metrics; configure which management endpoints are accessible and avoid exposing sensitive configuration. Add low-cardinality observations around meaningful business operations. OpenTelemetry SDK/agent instrumentation and collectors can export traces/metrics/logs through chosen backends; avoid duplicate instrumentation that records the same call twice.')+p('On AWS, CloudWatch supplies metrics/log destinations and alarms; ADOT/OpenTelemetry pipelines can export supported telemetry to AWS services and other backends. X-Ray or another trace backend helps follow distributed calls, but propagation conventions across gateways, SDKs and queue workers must be tested. Infrastructure logs alone do not know the business state of an order.')+p('Retain structured errors with request and business references, not full payloads. Restrict telemetry access, encrypt appropriately and define retention by data class. Redaction should happen before export; deleting a secret later from one dashboard may not remove all copies.')),
section('worked','Worked design: missing fulfillment investigation',p('Order ord_7 was accepted at 10:00. The durable order ledger shows PAID. Find its OrderPaid outbox row by order ID; the relay published evt_91. Broker delivery metrics are healthy, but fulfillment inbox shows evt_91 failed on an unsupported schema version and went to quarantine.')+p('The HTTP trace only covers acceptance because the event was consumed later and sampling omitted that consumer trace. Durable event identity and structured failure records still explain the outcome. Fix the reader compatibly, replay the same event ID under an authorized recovery operation, and check the conditional fulfillment transition so replay cannot create a second shipment.')+p('Add an alert on paid-to-fulfillment age with a clear owner/runbook rather than merely alerting on queue depth. Verify the final outcome in the business ledger and preserve an audit record for the replay. This makes the investigation reproducible even when individual traces have expired.')),
section('alerts','Alerts and tricky interpretation',table(['Trap','Why it misleads','Better practice'],[['All 202 responses counted as success','Background work may never finish','Measure acceptance and completion separately.'],['p99 from averaged pod p99 values','Percentiles are not additive','Aggregate compatible histograms/distributions.'],['Every trace sampled','Cost and sensitive-data exposure grow','Intentional sampling plus independent core metrics/audits.'],['No logs means no errors','Exporter or pipeline may be broken','Monitor telemetry delivery/drop health.']])+p('Alert on actionable symptoms and SLO risk, then attach diagnostic context. Error-budget burn compares observed bad-event consumption to the allowed budget. Use suitable short and long windows so fast incidents and slow persistent degradation are both visible. A runbook should name the invariant, safe mitigation and evidence needed to confirm recovery.')),
section('interview','Interview ladder',qa([['Foundational','Logs versus traces?','Logs record events; traces connect timed operations across execution boundaries. Shared IDs can link them, but neither automatically replaces the other.'],['Foundational','What is an SLO?','A target over a defined SLI and measurement window, such as 99% of eligible accepted orders completing within five minutes.'],['Intermediate','Why did MDC disappear in an async task?','Thread-bound logging state does not automatically cross executor/reactive/message boundaries. Use scoped context capture/restore through supported mechanisms and test cleanup to avoid leakage.'],['Intermediate','Why not label metrics with order ID?','It creates a growing time series for every order and can expose sensitive identity. Put it in controlled logs/traces; metrics need bounded dimensions.'],['Advanced','How do you investigate with no retained trace?','Use durable business state, event IDs, structured outcomes and audit records. Traces are sampled evidence, not the only recovery ledger.'],['Advanced','Does ScopedValue replace distributed tracing?','No. It can carry scoped in-process state. HTTP/message propagation, span creation, sampling, logging integration and durable business identity are separate responsibilities.'] ])),
section('references','Further reading and practice',refs([['https://opentelemetry.io/docs/concepts/signals/','OpenTelemetry signals','metrics, logs, traces and their roles.'],['https://opentelemetry.io/docs/concepts/context-propagation/','OpenTelemetry propagation','context carriers and boundaries.'],['https://www.w3.org/TR/trace-context/','W3C Trace Context','interoperable headers and trust considerations.'],['https://docs.spring.io/spring-boot/reference/actuator/tracing.html','Spring Boot tracing','supported integration and client instrumentation.'],['https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/lang/ScopedValue.html','Java ScopedValue','scope and inheritance rules for context.']])+p('<strong>Exercise:</strong> trace one asynchronous business outcome with IDs from HTTP acceptance through outbox, broker, inbox and final state. Identify what survives when traces are sampled out.'))
]}
];
deepenLessons(lessons);
lessons.push(...additionalLessons);
